def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn_parts):
        total = 0
        for i, digit in enumerate(isbn_parts):
            total += (i + 1) * int(digit)
        checksum = total % 11
        return 'X' if checksum == 10 else str(checksum)

    try:
        # Remove hyphens and check if the length is correct
        isbn_clean = isbn.replace('-', '')
        if len(isbn_clean) != 10:
            raise ValueError("ISBN must be 10 characters long without hyphens")

        # Extract the provided checksum
        provided_checksum = isbn_clean[-1]
        isbn_digits = isbn_clean[:-1]

        # Calculate the correct checksum
        correct_checksum = calculate_checksum(isbn_digits)

        # Compare the provided checksum with the correct checksum
        if provided_checksum == correct_checksum:
            return "Right"
        else:
            # Correct the ISBN by replacing the last character with the correct checksum
            corrected_isbn = isbn[:-1] + correct_checksum
            return corrected_isbn

    except (ValueError, IndexError) as e:
        return f"Invalid ISBN: {str(e)}"

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    try:
        if M <= 0 or N <= 0 or K < 0 or L < 0 or D < 0:
            raise ValueError("Invalid dimensions or number of aisles/chats.")

        row_counts = [0] * (M + 1)
        col_counts = [0] * (N + 1)

        for (Xi, Yi), (Pi, Qi) in chatting_pairs:
            if not (1 <= Xi <= M and 1 <= Yi <= N and 1 <= Pi <= M and 1 <= Qi <= N):
                raise ValueError("Chatting pair positions are out of classroom bounds.")

            if Xi == Pi:
                min_col, max_col = min(Yi, Qi), max(Yi, Qi)
                for col in range(min_col, max_col):
                    row_counts[Xi] += 1
            elif Yi == Qi:
                min_row, max_row = min(Xi, Pi), max(Xi, Pi)
                for row in range(min_row, max_row):
                    col_counts[Yi] += 1

        sorted_row_indices = sorted(range(1, M + 1), key=lambda x: row_counts[x], reverse=True)
        sorted_col_indices = sorted(range(1, N + 1), key=lambda x: col_counts[x], reverse=True)

        optimal_rows = ' '.join(map(str, sorted_row_indices[:K]))
        optimal_cols = ' '.join(map(str, sorted_col_indices[:L]))

