def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    if n < 0 or m < 0 or any(price < 0 or importance < 0 for price, importance in items):
        raise ValueError("Budget, number of items, and item prices and importances must be non-negative.")

    dp = [0] * (n + 1)

    for price, importance in items:
        for budget in range(n, price - 1, -1):
            dp[budget] = max(dp[budget], dp[budget - price] + price * importance)

    return max(dp)

def max_energy(beads):
    n = len(beads)
    if n < 3:
        return 0

    # Extend the beads to simulate the circular nature
    beads = beads + beads

    # dp[i][j] will store the maximum energy obtainable for merging beads from i to j
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for length in range(2, n + 1):
        for i in range(n):
            j = i + length
            if j > n:
                break
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    return max(dp[i][i + n] for i in range(n))

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if n < 0 or len(coeffs) != n + 1:
        raise ValueError("Invalid input: n must be non-negative and coeffs must have n+1 elements.")

    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        sign = '+' if coeff > 0 else '-'
        abs_coeff = abs(coeff)

        if degree == 0:
            term = f"{abs_coeff}"
        elif degree == 1:
            term = "x"
        else:
            term = f"x^{degree}"

        if abs_coeff != 1 or degree == 0:
            term = f"{abs_coeff}{term}"

        terms.append(f"{sign}{term}")

    if not terms:
        return "0"

    # Remove the leading '+' sign
    if terms[0].startswith('+'):
        terms[0] = terms[0][1:]

    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    try:
        for enc_char, orig_char in zip(encoded, original):
            if enc_char in mapping:
                if mapping[enc_char] != orig_char:
                    return "Failed"
            else:
                mapping[enc_char] = orig_char
    except Exception:
        return "Failed"

    if len(mapping) != len(set(original)):
        return "Failed"

    try:
        decoded_message = ''.join(mapping[char] for char in message)
    except KeyError:
        return "Failed"

    return decoded_message

def largest_prime_factor(n: int) -> int:
    if n <= 1:
        raise ValueError("Input must be a positive integer greater than 1.")

    # Start checking for factors from the smallest prime number
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            # Since n is the product of two distinct primes, n // i will be the larger prime
            return n // i

    # If no factors are found, n itself is a prime number (though per problem statement, n should not be prime)
    return n

def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x or k <= 0 or x <= 0:
        return 0

    def helper(n, k, x):
        if k == 1:
            return 1 if n >= x else 0
        if n < k * x:
            return 0
        return helper(n - x, k - 1, x) + helper(n - k, k, x + 1)

    try:
        return helper(n, k, x)
    except RecursionError:
        return -1  # Indicating that the recursion limit was reached

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last <= 0 or n <= 0:
        return 0
    if last in memo:
        return memo[last]

    count = 1  # The sequence consisting of just 'n' is always valid
    for i in range(1, last // 2 + 1):
        count += count_sequences(n, i, memo)

    memo[last] = count
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    if x0 <= 0 or y0 <= 0 or y0 % x0 != 0:
        return 0

    from math import gcd

    count = 0
    target = y0 // x0

    for a in range(1, int(target**0.5) + 1):
        if target % a == 0:
            b = target // a
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2

    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder or len(inorder) != len(postorder):
        raise ValueError("Invalid input: Inorder and postorder traversals must be non-empty and of the same length.")

    def build_tree(inorder, postorder):
        if not inorder or not postorder:
            return None

        root_value = postorder[-1]
        root_index = inorder.index(root_value)

        left_inorder = inorder[:root_index]
        right_inorder = inorder[root_index + 1:]

        left_postorder = postorder[:root_index]
        right_postorder = postorder[root_index:-1]

        root = {
            'value': root_value,
            'left': build_tree(left_inorder, left_postorder),
            'right': build_tree(right_inorder, right_postorder)
        }

        return root

    def get_preorder(node):
        if not node:
            return ''
        return node['value'] + get_preorder(node['left']) + get_preorder(node['right'])

    tree = build_tree(inorder, postorder)
    return get_preorder(tree)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque

    if A == B:
        return 0

    queue = deque([(A, 0)])
    visited = set([A])

    while queue:
        current, steps = queue.popleft()

        if steps >= 10:
            continue

        for source, target in rules:
            index = current.find(source)
            while index != -1:
                new_string = current[:index] + target + current[index + len(source):]
                if new_string == B:
                    return steps + 1
                if new_string not in visited:
                    visited.add(new_string)
                    queue.append((new_string, steps + 1))
                index = current.find(source, index + 1)

    return "NO ANSWER!"

