def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    from collections import deque, defaultdict

    # Create a mapping of each digit to its possible transformations
    transform_map = defaultdict(set)
    for x, y in rules:
        transform_map[x].add(y)

    # Convert the number to a string for easy manipulation
    original_number = str(n)
    queue = deque([original_number])
    seen = set([original_number])

    while queue:
        current_number = queue.popleft()
        for i, digit in enumerate(current_number):
            if int(digit) in transform_map:
                for new_digit in transform_map[int(digit)]:
                    new_number = current_number[:i] + str(new_digit) + current_number[i+1:]
                    if new_number not in seen:
                        seen.add(new_number)
                        queue.append(new_number)

    return len(seen)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    try:
        for participant, participant_statements in statements.items():
            for statement in participant_statements:
                if any(day in statement for day in days_of_week):
                    continue  # Skip statements that are about the day of the week

                if participant in liar_count:
                    # If the participant is a liar, their statement should be false
                    if scenario.lower() in statement.lower() and "not" in statement.lower():
                        continue  # Liar claims the scenario is not true (which is false, so consistent)
                    elif scenario.lower() not in statement.lower() and "not" not in statement.lower():
                        continue  # Liar claims something else, which is false (consistent)
                    else:
                        return False  # Liar makes a statement that is true, which is inconsistent

                else:
                    # If the participant is not a liar, their statement should be true
                    if scenario.lower() in statement.lower() and "not" not in statement.lower():
                        continue  # Truth-teller claims the scenario is true, which is consistent
                    elif scenario.lower() not in statement.lower() and "not" in statement.lower():
                        continue  # Truth-teller claims the scenario is not true, which is consistent
                    else:
                        return False  # Truth-teller makes a statement that is false, which is inconsistent

        return True  # All statements are consistent with the scenario

    except Exception as e:
        return False  # Return False in case of any unexpected error

def calculate_score(system: int, points: str) -> list:
    if system not in [11, 21]:
        raise ValueError("System must be either 11 or 21.")
    if not all(char in 'WL' for char in points):
        raise ValueError("Points string must only contain 'W' or 'L'.")

    player_score = 0
    opponent_score = 0
    scores = []

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1

        # Check if the game is finished
        if (player_score >= system or opponent_score >= system) and abs(player_score - opponent_score) >= 2:
            scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    # If there's any unfinished game, append the current score
    if player_score > 0 or opponent_score > 0:
        scores.append(f"{player_score}:{opponent_score}")

    return scores

def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("The input must be a non-negative integer.")

    # Initialize a table to store results of subproblems
    catalan = [0] * (n + 1)

    # Base case
    catalan[0] = 1

    # Fill entries in catalan[] using recursive formula
    for i in range(1, n + 1):
        catalan[i] = 0
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - j - 1]

    return catalan[n]

