def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    if T < 0 or M < 0 or any(t < 0 or v < 0 for t, v in herbs):
        raise ValueError("Time, number of herbs, and herb values must be non-negative.")

    # Initialize a list to store the maximum value at each time up to T
    dp = [0] * (T + 1)

    # Iterate over each herb
    for t, v in herbs:
        # Update the dp array from back to front to avoid overwriting values needed for current iteration
        for i in range(T, t - 1, -1):
            dp[i] = max(dp[i], dp[i - t] + v)

    return dp[T]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    if V < 0 or n < 0 or any(vol < 0 for vol in volumes):
        raise ValueError("Volume, number of items, and individual item volumes must be non-negative.")
    if n != len(volumes):
        raise ValueError("The number of items must match the length of the volumes list.")

    dp = [0] * (V + 1)

    for volume in volumes:
        for j in range(V, volume - 1, -1):
            dp[j] = max(dp[j], dp[j - volume] + volume)

    return V - dp[V]

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            dp[i][j] = dp[i - 1][j]
            for k in range(1, min(a[i - 1], j) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    if not key.isalpha() or not ciphertext.isalpha():
        raise ValueError("Key and ciphertext must consist only of alphabetic characters.")

    key = key.lower()
    ciphertext = ciphertext.lower()
    key_length = len(key)
    decrypted_text = []

    for i, char in enumerate(ciphertext):
        key_char = key[i % key_length]
        shift = ord(key_char) - ord('a')
        decrypted_char = chr((ord(char) - ord('a') - shift) % 26 + ord('a'))
        decrypted_text.append(decrypted_char)

    return ''.join(decrypted_text)

def mod_inverse(a, b):
    def extended_gcd(aa, bb):
        if aa == 0:
            return bb, 0, 1
        gcd, x1, y1 = extended_gcd(bb % aa, aa)
        x = y1 - (bb // aa) * x1
        y = x1
        return gcd, x, y

    gcd, x, _ = extended_gcd(a, b)
    if gcd != 1:
        return None
    else:
        return x % b

