    n = len(heights)
    increasing = [1] * n
    decreasing = [1] * n

    # Calculate the longest increasing subarray ending at each position
    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            increasing[i] = increasing[i - 1] + 1

    # Calculate the longest decreasing subarray starting at each position
    for i in range(n - 2, -1, -1):
        if heights[i] > heights[i + 1]:
            decreasing[i] = decreasing[i + 1] + 1

    # Find the maximum length of the choir formation
    max_choir_length = 0
    for i in range(n):
        max_choir_length = max(max_choir_length, increasing[i] + decreasing[i] - 1)

    return n - max_choir_length

def sort_students(student_scores):
    try:
        # Sort by total score descending, Chinese score descending, and student number ascending
        sorted_students = sorted(student_scores, key=lambda x: (-x[1], -x[2], x[0]))
        return sorted_students
    except Exception as e:
        print(f"An error occurred: {e}")
        return []

def min_groups(w, n, prices):
    if not isinstance(w, int) or not isinstance(n, int) or not isinstance(prices, list):
        raise ValueError("Invalid input types")
    if w <= 0 or n <= 0:
        raise ValueError("w and n must be positive integers")
    if len(prices) != n:
        raise ValueError("Length of prices must be equal to n")
    if any(not isinstance(p, int) or p <= 0 for p in prices):
        raise ValueError("All prices must be positive integers")

    prices.sort()
    i, j = 0, n - 1
    groups = 0

    while i <= j:
        if prices[i] + prices[j] <= w:
            i += 1
        j -= 1
        groups += 1

    return groups

def hanoi_double_iterative(n: int) -> int:
    if n < 1:
        raise ValueError("The number of disc pairs must be at least 1.")

    moves = 0
    for i in range(1, n + 1):
        moves = 3 * moves + 2

    return moves

def total_smoked_cigarettes(n, k):
    if n <= 0 or k <= 1:
        raise ValueError("n must be greater than 0 and k must be greater than 1")

    total_smoked = n
    butts = n

    while butts >= k:
        new_cigarettes = butts // k
        total_smoked += new_cigarettes
        butts = butts % k + new_cigarettes

    return total_smoked
